/**
 * 显式启动（main.tsx 在 createRoot 之前调）。
 * 不做幂等短路的外部判断，只在这里守一次，HMR 后仍能重新订阅。
 */
export function startEngine(): void {
  if (off) return
  const api = window.pi?.agent
  // 浏览器里预览（无 preload）时降级为静态，不崩
  if (!api) {
    engine.set({ error: '未连接到引擎（浏览器预览）' })
    off = () => {}
    return
  }
  const stop = api.onEvent(dispatch)
  off = () => {
    stop()
    clearTimers()
  }
  api.send({ type: 'init' })
}

/** Vite 热重载前退订：否则改一次本文件就多一个 ipcRenderer.on，旧 dispatch 指着废弃的 store */
const hot = (import.meta as unknown as { hot?: { dispose(cb: () => void): void } }).hot
hot?.dispose(() => {
  off?.()
  off = null
})

